effect.shader:
float h(float x){return fract(sin(x*127.1)*43758.5453);}void main(){vec2 uv=acScreenNorm,q=uv-vanishingPoint;float a=atan(q.y,q.x)+rotation,r=length(q);float sectors=180.0;float id=floor((a/6.2831853+.5)*sectors);float rnd=h(id+floor(evolution));float local=abs(fract((a/6.2831853+.5)*sectors)-.5);float radial=fract(r/max(trailLength,.001)-evolution*.07+rnd);float line=step(1.0-density,rnd)*(1.0-smoothstep(thickness,thickness*2.2,local))*(1.0-smoothstep(.25,.95,radial))*smoothstep(.02,.2,r);line*=intensity;vec4 src=texture2DCv(inputImg.texture,uv);vec3 light=lineColor.rgb*line;vec3 outRgb=1.0-(1.0-src.rgb)*(1.0-clamp(light,0.0,1.0));gl_FragColor=vec4(mix(src.rgb,outRgb,mixAmount),src.a+clamp(line,0.0,1.0)*mixAmount*(1.0-src.a));
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
